nsImapMailFolder::ParseAdoptedMsgLine(const char* adoptedMessageLine,
                                      ImapUid uidOfMessage,
                                      nsIImapUrl* aImapUrl) {
  NS_ENSURE_ARG_POINTER(aImapUrl);
  uint32_t count = 0;
  nsresult rv;
  if (!m_offlineHeader) {
    // If the folder is locked by anything other than itself,
    // we want to fail immediately.
    // Examples:
    // During compaction, FolderCompactor holds the lock.
    // During DownloadAllForOffline(), the folder locks itself.
    bool isLocked;
    GetLocked(&isLocked);
    if (isLocked) {
      // It's OK if we, the folder, have the semaphore.
      bool hasSemaphore = false;
      TestSemaphore(static_cast<nsIMsgFolder*>(this), &hasSemaphore);
      if (!hasSemaphore) {
        NS_WARNING("ParseAdoptedMsgLine: folder is locked.");
        return NS_MSG_FOLDER_BUSY;
      }
    }

    // Starting a new message.

    if (m_runningUrl)
      m_runningUrl->GetStoreResultsOffline(&echoLineToMessageSink);

    m_bytesToChannel += byteCount;
    if (m_imapMessageSink && line && echoLineToMessageSink &&
        !GetPseudoInterrupted()) {
      nsresult rv = m_imapMessageSink->ParseAdoptedMsgLine(line, uidOfMessage,
                                                           m_runningUrl);
      if (NS_FAILED(rv)) {
        // If the folder failed to accept the message, stop piping it across!
        PseudoInterrupt(true);
      }
    }
  }
  // ***** We need to handle the pseudo interrupt here *****
}
